 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function makeBucket(p, key, states) {
  // tokens are stored scaled by `per`, so fractions stay exact.
  return {
    advance(tick) {
      let s = states.get(key)
      if (!s) { s = { tokens: p.capacity * p.per, last: tick }; states.set(key, s); return }
      const n = tick - s.last
      s.last = tick
      s.tokens += p.refill * n
      const cap = p.capacity * p.per
      if (s.tokens > cap) s.tokens = cap
    },
    allows() { return states.get(key).tokens >= p.per },
    record() { states.get(key).tokens -= p.per },
  }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].trim()
    if (t === '' || t.startsWith('#')) continue
    const w = t.split(/\s+/)
    const fail = (r) => new Fail(`error: line ${i + 1}: ${r}`)
    const int = (field, v, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) throw fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = w[0]
    if (d === 'bucket' || d === 'window') {
      const isB = d === 'bucket'
      if (w.length !== (isB ? 5 : 4)) throw fail(isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      if (lastTick !== null) throw fail('declarations must come before the first event')
      if (!NAME.test(w[1])) throw fail(`invalid policy name ${w[1]}`)
      let p
      if (isB) p = { type: 'bucket', name: w[1], capacity: int('capacity', w[2], 1), refill: int('refill', w[3], 0), per: int('per', w[4], 1), states: new Map() }
      else p = { type: 'window', name: w[1], limit: int('limit', w[2], 0), span: int('span', w[3], 1), states: new Map() }
      if (policies.has(p.name)) throw fail(`policy ${p.name} is declared twice`)
      policies.set(p.name, p)
    } else if (d === 'route') {
      if (w.length < 3) throw fail('expected route <prefix> <policy>...')
      if (lastTick !== null) throw fail('declarations must come before the first event')
      if (!NAME.test(w[1])) throw fail(`invalid route prefix ${w[1]}`)
      if (routes.has(w[1])) throw fail(`prefix ${w[1]} is routed twice`)
      const list = []
      for (const n of w.slice(2)) {
        if (!policies.has(n)) throw fail(`unknown policy ${n}`)
        list.push(policies.get(n))
      }
      routes.set(w[1], list)
    } else if (d === 'event') {
      if (w.length !== 3) throw fail('expected event <tick> <key>')
      const tick = int('tick', w[1], 0)
      if (!NAME.test(w[2])) throw fail(`invalid key ${w[2]}`)
      if (lastTick !== null && tick < lastTick) throw fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: w[2] })
    } else {
      throw fail(`unknown directive ${d}`)
    }
  }
  return { routes, events }
}

function run({ routes, events }) {
  const out = []
  const counts = new Map()
  for (const { tick, key } of events) {
    let best = null
    for (const pre of routes.keys()) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    let denied = null
    if (best !== null) {
      const acts = routes.get(best).map((p) => {
        if (p.type === 'bucket') return { p, ...makeBucket(p, key, p.states) }
        return {
          p,
          advance() {
            const l = (p.states.get(key) ?? p.states.set(key, []).get(key))
            while (l.length && l[0] <= tick - p.span) l.shift()
          },
          allows() { return BigInt(p.states.get(key).length) < p.limit },
          record() { p.states.get(key).push(tick) },
        }
      })
      for (const a of acts) a.advance(tick)
      for (const a of acts) if (!a.allows()) { denied = a.p.name; break }
      if (denied === null) for (const a of acts) a.record()
    }
    out.push(denied === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denied}`)
    const c = counts.get(key) ?? { a: 0, d: 0 }
    if (denied === null) c.a++; else c.d++
    counts.set(key, c)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  let a = 0
  let d = 0
  let s = ''
  for (const k of [...counts.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    const c = counts.get(k)
    a += c.a
    d += c.d
    s += `${k} allowed=${c.a} denied=${c.d}\n`
  }
  return s + `total allowed=${a} denied=${d}\n`
}

try {
  const result = run(parse(readFileSync(0, 'utf8')))
  process.stdout.write(result)
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
